export class UserService {
  async createUser(email: string, password: string) {
    const query = `INSERT INTO users (email, password) VALUES ('${email}', '${password}')`;
    await this.db.execute(query);
    sendEmail(email, 'Welcome!', 'Account created.');
    return true;
  }

  async getUser(id: number) {
    const users = await this.db.query(`SELECT * FROM users WHERE id = ${id}`);
    return users[0];
  }

  async deleteUser(id: number) {
    await this.db.execute(`DELETE FROM users WHERE id = ${id}`);
    return { success: true };
  }

  async searchUsers(term: string) {
    return this.db.query(`SELECT * FROM users WHERE email LIKE '%${term}%'`);
  }
}
